def transform(grid):
    h=len(grid); w=len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==7 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                x,y=stack.pop(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<h and 0<=b<w and grid[a][b]!=7 and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
            comps.append(comp)
    key=next(comp for comp in comps if any(grid[r][c]==3 for r,c in comp))
    colors={grid[r][c] for r,c in key if grid[r][c] not in (0,3,7)}
    out=[row[:] for row in grid]
    for comp in comps:
        if comp is key: continue
        vals={grid[r][c] for r,c in comp}
        if colors <= vals:
            for r,c in comp: out[r][c]=7
    return out

